    function ownerWindow(depth){if((depth||0)===0){var f=ownerFrame(0);if(f.getWindow)return f.getWindow();}try{var of=ownerFrame(depth||0);if(of&&of.getWindow)return of.getWindow();}catch(e){if((depth||0)===0)throw e;}return parentWindow(depth||1);}
