    function openerWindow(){if(scwin&&scwin.__xpOpenerScope)return scwin.__xpOpenerScope;try{if(typeof window!=='undefined'&&window.opener)return window.opener;}catch(e){throw runtimeError('OPENER_SCOPE_NOT_FOUND','window.opener access failed',{error:e});}throw runtimeError('OPENER_SCOPE_NOT_FOUND','popup opener scope is not available; inject scwin.__xpOpenerScope for framework popup bridges');}
